def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    opp_D = 0
    my_D = 0
    for me, op in history:
        if op == 'D':
            opp_D += 1
        if me == 'D':
            my_D += 1

    recent_len = min(20, n)
    start = n - recent_len
    recent_opp_D = 0
    for idx in range(start, n):
        me, op = history[idx]
        if op == 'D':
            recent_opp_D += 1

    tail_cc = 0
    idx = n - 1
    while idx >= 0:
        me, op = history[idx]
        if me == 'C' and op == 'C':
            tail_cc += 1
            idx -= 1
        else:
            break

    tail_opp_C = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][1] == 'C':
            tail_opp_C += 1
            idx -= 1
        else:
            break

    tail_my_D = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][0] == 'D':
            tail_my_D += 1
            idx -= 1
        else:
            break

    confirmed = False
    scan_start = n - 60
    if scan_start < 0:
        scan_start = 0

    for i in range(scan_start, n - 1):
        me_i, op_i = history[i]
        if me_i != 'D' or op_i != 'C':
            continue

        me_j, op_j = history[i + 1]
        if me_j != 'C' or op_j != 'C':
            continue

        if i > 0:
            me_prev, op_prev = history[i - 1]
            if me_prev != 'C' or op_prev != 'C':
                continue
        else:
            continue

        if tail_opp_C >= n - (i + 1) and opp_D * 2 < n and recent_opp_D <= 3:
            confirmed = True
            break

    if confirmed:
        if tail_my_D >= 5:
            return 'C'
        return 'D'

    my_last, opp_last = history[-1]

    if n >= 2:
        prev_my, prev_op = history[-2]
    else:
        prev_my = ''
        prev_op = ''

    if opp_D * 2 > n or (n >= 12 and recent_opp_D >= 7):
        return 'D'

    if opp_last == 'D':
        if my_last == 'C' and prev_my == 'C' and prev_op == 'D':
            return 'D'

        if my_last == 'C' and prev_my == 'D':
            if recent_opp_D <= 4 and opp_D * 100 < n * 35:
                return 'C'
            return 'D'

        if my_last == 'D':
            if recent_opp_D <= 4 and opp_D * 100 < n * 35:
                return 'C'
            return 'D'

        return 'D'

    if my_last == 'D':
        return 'C'

    if opp_D == 0 and my_D == 0 and n >= 20 and tail_cc >= 20:
        return 'D'

    if opp_D * 100 > n * 40 or recent_opp_D >= 5:
        return 'D'

    return 'C'
